<script setup>
import AccountSelect from '../components/AccountSelect.vue';
import BulkOperationsPanel from '../components/BulkOperationsPanel.vue';
import {focusError,firstField} from '../lib/entry-focus';
import DateInput from '../components/DateInput.vue';
import AccountPlanPanel from '../components/AccountPlanPanel.vue';
import {ref,computed,onUnmounted,nextTick,watch} from 'vue';
import Icon from '../components/Icon.vue';import BaseModal from '../components/BaseModal.vue';import EmptyState from '../components/EmptyState.vue';
import {state,company,api,scope,useResource,rows,notify,changed,ask} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';
import {money,date,amount,cents,periodDate,uid,statusLabel,normalized} from '../lib/format';
const selectedIds=ref([]),bulkBusy=ref(false);
function toggleSelection(id,checked){if(bulkBusy.value)return;selectedIds.value=checked?[...new Set([...selectedIds.value,id])]:selectedIds.value.filter(x=>x!==id);}
const props=defineProps({initialSection:{type:String,default:'journals'}});
const monthFilter=ref('');
const routine=computed(()=>section.value==='journals'?'accounting.journals':section.value==='accounts'?'accounting.accounts':'accounting.cost_centers');
const section=ref(props.initialSection),q=ref(''),show=ref(false),kind=ref('journal'),busy=ref(false),error=ref(''),form=ref({}),context=ref({}),detail=ref(null);let baseline='';
const {data,loading,error:loadError}=useResource(async()=>{if(!state.companyId)return {journals:[],accounts:[],centers:[]};const [j,a,c,h]=await Promise.all([allowedApi('accounting.journals',scope(`/journals?year=${state.period.slice(0,4)}`)),allowedApi('accounting.accounts',scope('/accounts')),allowedApi('accounting.cost_centers',scope('/cost-centers')),allowedApi('accounting.histories',scope('/masters/history'))]);return {journals:rows(j),accounts:rows(a),centers:rows(c),histories:h};},{journals:[],accounts:[],centers:[],histories:[]});
const list=computed(()=>data.value[section.value==='cost-centers'?'centers':section.value].filter(x=>(!monthFilter.value||!x.period||x.period.slice(5)===monthFilter.value)&&normalized(JSON.stringify(x)).includes(normalized(q.value))));
const page=ref(1),pageSize=ref(50);
const visible=computed(()=>section.value==='cost-centers'?list.value:list.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
watch([q,monthFilter,section,pageSize,()=>state.companyId,()=>state.period,()=>data.value.journals],()=>page.value=1);
const exportUrl=computed(()=>`/api${scope('/movement-exports/journals.xlsx')}?${new URLSearchParams({year:state.period.slice(0,4),month:monthFilter.value,query:q.value})}`);
const debit=computed(()=>form.value.lines?.reduce((s,l)=>s+(cents(l.debit)||0),0)||0),credit=computed(()=>form.value.lines?.reduce((s,l)=>s+(cents(l.credit)||0),0)||0);
const validBalance=computed(()=>debit.value>0&&debit.value===credit.value);
const retain=ref({date:true,history:false,center:false});
const saveNext=ref(false);
const blankLine=()=>({account_id:'',cost_center_id:'',debit:'',credit:''});
function open(type='journal',record=null){kind.value=type;context.value={id:state.companyId,name:company.value?.trade_name||company.value?.name,code:company.value?.code,tax_id:company.value?.tax_id,period:state.period};detail.value=null;error.value='';
 if(type==='journal')form.value={date:periodDate(state.period),document:'',history:'',idempotency_key:uid(),lines:[blankLine(),blankLine()]};
 else if(type==='account')form.value=record?{...record}:{access_code:'',classifier:'',name:'',nature:'debit',analytical:true,requires_cost_center:false,report_group:'',prosoft_code:''};
 else form.value=record?{...record}:{code:'',name:''};
 baseline=JSON.stringify(form.value);show.value=true;state.editor={name:type==='journal'?'Lançamento contábil':'Cadastro contábil',companyId:state.companyId};}
async function close(){if(busy.value)return;if(!detail.value&&baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'As alterações desta janela ainda não foram gravadas.',confirmLabel:'Descartar',danger:true}))return;show.value=false;detail.value=null;state.editor=null;}
async function addLine(){form.value.lines.push(blankLine());await nextTick();document.querySelector('#journal-form .entry-line:last-child select')?.focus();}
function submitNext(){const form=document.getElementById('journal-form');if(form?.reportValidity()){saveNext.value=true;form.requestSubmit()}}
async function save(){if(busy.value)return;error.value='';if(kind.value==='journal'&&!form.value.date.startsWith(context.value.period.slice(0,4))){error.value='A data deve pertencer ao exercício em uso.';focusError('journal-form',error.value);return;}busy.value=true;
 try{let path,payload;if(kind.value==='journal'){path=form.value.opening?'/opening-balances':'/journals';payload={...form.value,lines:form.value.lines.map(l=>({...l,account_id:Number(l.account_id),cost_center_id:l.cost_center_id?Number(l.cost_center_id):null,debit:amount(l.debit),credit:amount(l.credit)}))};}else{path=kind.value==='account'?'/accounts':'/cost-centers';payload=form.value;}
 await api(scope(path+(form.value.id?`/${form.value.id}`:''),context.value.id),{method:form.value.id?'PUT':'POST',body:payload});const previous={...form.value};const another=saveNext.value&&kind.value==='journal'&&!form.value.opening;saveNext.value=false;if(another){open('journal');if(retain.value.date)form.value.date=previous.date;if(retain.value.history)form.value.history=previous.history;if(retain.value.center)form.value.lines=form.value.lines.map((l,i)=>({...l,cost_center_id:previous.lines[i]?.cost_center_id||''}));baseline=JSON.stringify(form.value);await nextTick();firstField('journal-form');}else{show.value=false;state.editor=null;}changed();notify(kind.value==='journal'?'Lançamento escriturado na empresa indicada.':'Cadastro salvo.');}catch(e){error.value=e.message;saveNext.value=false;await nextTick();focusError(kind.value+'-form',e.message);}finally{busy.value=false;}}
async function inspect(j){try{let x=j;if(!j.lines)x=await api(scope(`/journals/${j.id}`));detail.value=x;kind.value='detail';context.value={id:state.companyId,name:company.value?.trade_name||company.value?.name,code:company.value?.code,period:state.period};show.value=true;state.editor={name:'Detalhes do lançamento',companyId:state.companyId};}catch(e){notify(e.message,'error');}}
async function reverse(){const reason=await ask({title:'Estornar lançamento',message:'Será criado um lançamento inverso, preservando o original e seu histórico.',confirmLabel:'Confirmar estorno',inputLabel:'Motivo do estorno',required:true,danger:true});if(!reason)return;busy.value=true;try{await api(scope(`/journals/${detail.value.id}/reverse`,context.value.id),{method:'POST',body:{date:periodDate(state.period),reason,idempotency_key:uid()}});show.value=false;state.editor=null;changed();notify('Estorno registrado com rastreabilidade.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
const accountName=id=>data.value.accounts.find(a=>a.id===id)?.name||id;
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">ESCRITURAÇÃO</div><h1>{{section==='journals'?'Lançamentos contábeis':section==='accounts'?'Plano de contas':'Centros de custo'}}</h1><p>Partidas, plano de contas e centros de custo no mesmo contexto.</p></div><button class="button primary" v-allow="[routine,'create']" @click="open(section==='journals'?'journal':section==='accounts'?'account':'center')"><Icon name="plus"/>{{section==='journals'?'Novo lançamento':section==='accounts'?'Nova conta':'Novo centro de custo'}}</button></header>

<AccountPlanPanel v-if="section==='accounts'"/>
<div v-if="loadError" class="message error">{{loadError}}</div><label class="operation-month">Competência da consulta<select v-model="monthFilter"><option value="">Todo o exercício</option><option v-for="m in 12" :value="String(m).padStart(2,'0')">{{String(m).padStart(2,'0')}}/{{state.period.slice(0,4)}}</option></select></label><section class="panel"><div class="table-toolbar"><div class="search-field"><Icon name="search"/><input v-model="q" :placeholder="section==='journals'?'Pesquisar documento ou histórico':'Pesquisar código ou nome'" aria-label="Pesquisar contabilidade"/></div><span class="badge neutral"><Icon name="calendar" :size="13"/>Exercício {{state.period.slice(0,4)}}</span><span class="count">{{list.length}} registros</span><label v-if="section!=='cost-centers'">Registros por página<select v-model.number="pageSize" aria-label="Registros por página"><option v-for="size in [50,100,250,500,1000,2500,5000]" :key="size" :value="size">{{size}}</option></select></label><a v-if="section==='journals'&&!loading&&!state.contextBusy&&state.companyId&&can('accounting.journals','read')&&can('accounting.journals','export')" class="button outline small" :href="exportUrl" download title="Exportar todos os registros que correspondem aos filtros, incluindo outras páginas">Exportar Excel ({{list.length}})</a></div>
<BulkOperationsPanel v-if="section==='journals'" kind="journals" :records="visible" v-model:selected-ids="selectedIds" :loading="loading" :reset-key="JSON.stringify([q,monthFilter,section,page,pageSize])" @busy="bulkBusy=$event"/><div v-if="loading" class="loading-line"><Icon name="loading"/>Carregando registros...</div><div v-else-if="list.length" class="table-scroll"><table v-if="section==='journals'"><thead><tr><th>Selecionar</th><th>Nº</th><th>Data</th><th>Documento / histórico</th><th class="right">Valor</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="j in visible" :key="j.id"><td><input type="checkbox" :checked="selectedIds.includes(j.id)" :disabled="bulkBusy||!can('accounting.journals','read')" :aria-label="`Selecionar lançamento ${j.number||j.id} (#${j.id})`" @change="toggleSelection(j.id,$event.target.checked)"/></td><td class="mono">{{j.number||j.id}}</td><td class="nowrap">{{date(j.date)}}</td><td><strong>{{j.document||'Sem documento'}}</strong><small class="cell-secondary">{{j.history}}</small></td><td class="right money">{{money(j.total_cents??j.debit_cents??j.lines?.reduce((s,l)=>s+(l.debit_cents||0),0))}}</td><td><span class="badge" :class="j.status==='reversed'?'neutral':'success'">{{statusLabel(j.status||'posted')}}</span></td><td><button class="icon-button" @click="inspect(j)" :aria-label="`Ver lançamento ${j.number||j.id}`"><Icon name="eye"/></button></td></tr></tbody></table>
<table v-else-if="section==='accounts'"><thead><tr><th>Acesso</th><th>Classificador</th><th>Nome da conta</th><th>Natureza</th><th>Tipo</th><th>Centro de custo</th><th></th></tr></thead><tbody><tr v-for="a in visible" :key="a.id"><td class="mono">{{a.access_code}}</td><td class="mono">{{a.classifier}}</td><td><strong>{{a.name}}</strong></td><td>{{a.nature==='debit'?'Devedora':'Credora'}}</td><td><span class="badge neutral">{{a.analytical?'Analítica':'Sintética'}}</span></td><td>{{a.requires_cost_center?'Obrigatório':'Opcional'}}</td><td><button class="icon-button" v-allow="['accounting.accounts','edit']" @click="open('account',a)" :aria-label="`Editar conta ${a.name}`"><Icon name="edit"/></button></td></tr></tbody></table>
<table v-else><thead><tr><th>Código</th><th>Centro de custo</th><th></th></tr></thead><tbody><tr v-for="c in list" :key="c.id"><td class="mono">{{c.code}}</td><td>{{c.name}}</td><td><button class="icon-button" v-allow="['accounting.cost_centers','edit']" @click="open('center',c)" :aria-label="`Editar centro ${c.name}`"><Icon name="edit"/></button></td></tr></tbody></table></div>
<EmptyState v-else :title="section==='journals'?'Nenhum lançamento neste período':'Nenhum cadastro encontrado'" :text="section==='journals'?'Crie um lançamento balanceado ou contabilize um documento conferido.':'Inclua os cadastros necessários para a escrituração.'" icon="journal"/><footer class="table-footer"><span>{{section==='journals'?'Lançamentos ficam vinculados à empresa e à competência exibidas.':'Código de acesso e classificador são informações distintas.'}}</span><span>{{list.length}} registros</span><div v-if="section!=='cost-centers'" class="actions"><span>Página {{page}} de {{Math.max(1,Math.ceil(list.length/pageSize))}}</span><button class="button small" @click="page--" :disabled="page===1">Anterior</button><button class="button small" @click="page++" :disabled="page*pageSize>=list.length">Próxima</button></div></footer></section>
<BaseModal v-if="show" :title="kind==='journal'?'Novo lançamento contábil':kind==='detail'?'Detalhes do lançamento':kind==='account'?(form.id?'Editar conta':'Nova conta'):(form.id?'Editar centro de custo':'Novo centro de custo')" :subtitle="`${context.code} · ${context.name} · ${'Exercício '+context.period.slice(0,4)}`" :wide="kind==='journal'||kind==='detail'" @close="close"><div class="context-notice"><Icon name="building"/><span>Empresa do {{kind==='journal'?'lançamento':'registro'}}: <strong>{{context.name}}</strong></span><span class="badge neutral">{{'Exercício '+context.period.slice(0,4)}}</span></div><div v-if="error" class="message error" role="alert">{{error}}</div>
<form v-if="kind==='journal'" id="journal-form" @submit.prevent="save"><div class="form-grid three"><label>Data do lançamento *<DateInput v-model="form.date" required :min="`${context.period.slice(0,4)}-01-01`" :max="`${context.period.slice(0,4)}-12-31`"/></label><label>Documento<input v-model="form.document" placeholder="Número ou referência"/></label><label class="span-3">Histórico cadastrado<select @change="form.history=data.histories.find(h=>h.id===Number($event.target.value))?.data.text||form.history"><option value="">Redigir nesta operação</option><option v-for="h in data.histories.filter(h=>h.active)" :value="h.id" :key="h.id">{{h.code}} · {{h.name}}</option></select></label><label class="span-3">Histórico *<input v-model="form.history" required placeholder="Descreva o fato contábil de forma objetiva" maxlength="500"/></label></div><label class="choice-card"><input type="checkbox" v-model="form.opening"/><div><strong>Saldos iniciais de implantação</strong><small>Um lote por data, com todas as contrapartidas. Para saldo anterior ao relatório, use a competência anterior e a data correspondente.</small></div></label><div class="section-label">Partidas <span>Débitos e créditos devem ter o mesmo total.</span></div>
<div class="entry-lines"><div class="entry-line line-labels"><span>Conta contábil *</span><span>Centro de custo</span><span>Débito (R$)</span><span>Crédito (R$)</span><span></span></div><div v-for="(line,i) in form.lines" :key="i" class="entry-line"><AccountSelect v-model="line.account_id" required :aria-label="`Conta da partida ${i+1}`" :accounts="data.accounts.filter(x=>x.analytical)" empty-label="Selecione a conta"/><select v-model.number="line.cost_center_id" :required="data.accounts.find(a=>a.id===line.account_id)?.requires_cost_center" :aria-label="`Centro de custo da partida ${i+1}`"><option value="">Sem rateio</option><option v-for="c in data.centers" :key="c.id" :value="c.id">{{c.code}} · {{c.name}}</option></select><input v-model="line.debit" class="money-input" inputmode="decimal" placeholder="0,00" :aria-label="`Débito da partida ${i+1}`"/><input v-model="line.credit" class="money-input" inputmode="decimal" placeholder="0,00" :aria-label="`Crédito da partida ${i+1}`"/><button class="icon-button danger-text" type="button" :disabled="form.lines.length<=2" @click="form.lines.splice(i,1)" :aria-label="`Remover partida ${i+1}`"><Icon name="trash" :size="16"/></button></div></div><button type="button" class="text-button" data-add-line @click="addLine"><Icon name="plus" :size="16"/>Adicionar partida</button><div class="entry-totals"><div><small>Total de débitos</small><strong>{{money(debit)}}</strong></div><div><small>Total de créditos</small><strong>{{money(credit)}}</strong></div><span class="balance" :class="validBalance?'balanced':'unbalanced'"><Icon :name="validBalance?'checks':'alert'"/>{{validBalance?'Lançamento equilibrado':`Diferença: ${money(debit-credit)}`}}</span></div></form>
<form v-else-if="kind==='account'" id="account-form" @submit.prevent="save"><div class="form-grid"><label>Código de acesso *<input v-model="form.access_code" required/></label><label>Classificador *<input v-model="form.classifier" required placeholder="1.1.01.001"/></label><label class="span-2">Nome da conta *<input v-model="form.name" required/></label><label>Natureza<select v-model="form.nature"><option value="debit">Devedora</option><option value="credit">Credora</option></select></label><label>Tipo<select v-model="form.analytical"><option :value="true">Analítica — aceita lançamentos</option><option :value="false">Sintética — agrupamento</option></select></label><label>Grupo nos demonstrativos<select v-model="form.report_group"><option value="">Não classificado</option><option value="asset">Ativo</option><option value="liability">Passivo</option><option value="equity">Patrimônio líquido</option><option value="revenue">Receita</option><option value="expense">Despesa</option></select></label><label>Acesso na Prosoft<input v-model="form.prosoft_code" maxlength="5"/></label><label class="check-label span-2"><input type="checkbox" v-model="form.requires_cost_center"/>Exigir centro de custo nas partidas desta conta</label></div></form>
<form v-else-if="kind==='center'" id="center-form" @submit.prevent="save"><div class="form-grid"><label>Código *<input v-model="form.code" required/></label><label>Nome *<input v-model="form.name" required/></label></div></form>
<div v-else-if="detail"><div class="detail-grid"><div><small>Data</small><strong>{{date(detail.date)}}</strong></div><div><small>Documento</small><strong>{{detail.document||'—'}}</strong></div><div><small>Situação</small><span class="badge success">{{statusLabel(detail.status)}}</span></div></div><p class="detail-history">{{detail.history}}</p><div class="table-scroll"><table><thead><tr><th>Conta</th><th>Centro de custo</th><th class="right">Débito</th><th class="right">Crédito</th></tr></thead><tbody><tr v-for="(l,i) in detail.lines" :key="i"><td>{{l.account_name||accountName(l.account_id)}}</td><td>{{data.centers.find(c=>c.id===l.cost_center_id)?.name||'—'}}</td><td class="right money">{{money(l.debit_cents)}}</td><td class="right money">{{money(l.credit_cents)}}</td></tr></tbody></table></div><div class="message subtle"><Icon name="shield"/><span>O estorno preserva o lançamento original e registra o motivo.</span></div></div>
<template #footer><span v-if="kind==='journal'&&!form.opening" class="entry-defaults">Manter: <label><input type="checkbox" v-model="retain.date"/>Data</label><label><input type="checkbox" v-model="retain.history"/>Histórico</label><label><input type="checkbox" v-model="retain.center"/>Centro</label></span><span class="footer-hint"><Icon name="lock" :size="15"/>Alt+S salvar · Alt+N salvar e novo · Ctrl+Enter partida · Esc fechar</span><div class="actions"><button class="button" @click="close" :disabled="busy">{{kind==='detail'?'Fechar':'Cancelar'}}</button><button v-if="kind==='detail'&&detail?.status!=='reversed'" class="button danger" v-allow="['accounting.journals','reverse']" @click="reverse" :disabled="busy"><Icon name="undo"/>Estornar</button><button v-if="kind==='journal'&&!form.opening" type="button" data-save-new class="button outline" :disabled="busy||!validBalance" @click="submitNext">Salvar e novo · Alt+N</button><button v-if="kind!=='detail'" class="button primary" type="submit" :form="`${kind}-form`" :disabled="busy||(kind==='journal'&&!validBalance)"><Icon :name="busy?'loading':'check'"/>{{kind==='journal'?'Escriturar lançamento':'Salvar cadastro'}}</button></div></template></BaseModal>
</div></template>
